<?php
namespace App\Jobs;
use App\Domain\Documents\Enums\DocumentStatus;use App\Domain\PdfProcessing\Services\PreservationProcessor;use App\Models\{CompressionProfile,DocumentFile};use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Queue\Queueable;use Illuminate\Support\Facades\DB;
class GenerateDocumentDerivatives implements ShouldQueue{use Queueable;public int $tries=3;public array $backoff=[30,120,600];public int $timeout=1200;public function __construct(public int $masterFileId,public ?int $profileId=null){$this->onQueue('pdf-processing');}public function handle(PreservationProcessor $processor):void{$master=DocumentFile::with('version.document')->findOrFail($this->masterFileId);if($master->file_role!=='MASTER')return;$profile=$this->profileId?CompressionProfile::findOrFail($this->profileId):CompressionProfile::where('is_default',true)->where('status','PUBLISHED')->firstOrFail();$processor->process($master,$profile);DB::transaction(function()use($master){$document=$master->version->document;$from=$document->status->value;$document->update(['status'=>DocumentStatus::PendingQc]);DB::table('document_status_history')->insert(['document_id'=>$document->id,'from_status'=>$from,'to_status'=>DocumentStatus::PendingQc->value,'reason'=>'Preservation derivatives generated and integrity checked','changed_by'=>$master->uploaded_by,'changed_at'=>now(),'created_at'=>now()]);$master->update(['processing_status'=>'PROCESSED','processed_at'=>now()]);});}public function failed(\Throwable $e):void{$master=DocumentFile::with('version.document')->find($this->masterFileId);if(!$master)return;$master->update(['processing_status'=>'FAILED']);$master->version->document->update(['status'=>DocumentStatus::ProcessingFailed]);}}
